import os,sys,subprocess

def test_independent_sessions_and_overlay(tmp_path):
    code="from argparse import Namespace\nfrom PySide6 import QtCore,QtWidgets as W\nfrom spectradesk.workbench import Workbench\nimport numpy as np\napp=W.QApplication([]);win=Workbench(Namespace(demo=True,smoke=None,renderer='raster'));win.show();errors=[]\ndef begin():\n try:\n  assert all(s.ready for s in win.sessions)\n  for index in range(4):\n   win.tabs.setCurrentIndex(index);assert win.align_button.isHidden()==(index<2)\n  from spectradesk.spectrum_plot import SpectrumPlot\n  assert all(isinstance(p,SpectrumPlot) and p.renderer=='raster' for p in [win.plot]+win.parallel_plots+[s.plot for s in win.sessions])\n  win.sessions[0].average.setValue(2);win.sessions[1].average.setValue(3)\n  camera=win.sessions[1];assert camera.camera_exposure.minimum()==7.8 and camera.camera_exposure.maximum()==33.3\n  camera.camera_exposure.setValue(20.0);assert camera.integration.value()==200\n  camera.update_integration(312);assert camera.camera_exposure.value()==31.2\n  win.start_all()\n except BaseException as e:errors.append(e);finish()\ndef check():\n try:\n  a,b=win.sessions\n  assert a.frame_data and b.frame_data\n  win.refresh();assert all(p.property('acquiring') for p in win.device_panels)\n  for panel,session in zip(win.device_panels,win.sessions):assert panel.isAncestorOf(session.measure_status) and panel.isAncestorOf(session.sampling_indicator)\n  assert a.frame_data['average']==2 and b.frame_data['average']==3\n  assert b.frame_data['backend']=='camera' and b.frame_data['mean'].max()<255\n  win.tabs.setCurrentIndex(3);win.refresh();assert [win.tabs.tabText(i) for i in range(4)]==['FLA5000','摄像头光谱仪','叠加','上下显示'];assert win.parallel.orientation()==QtCore.Qt.Orientation.Vertical;assert all(c.isVisible() for c in win.device_controls);assert len(win.device_cards)==2 and win.sidepanel.isVisible();win.sessions[1].mode.setCurrentIndex(2);win.refresh();assert win.parallel_curves[1].opts['fillLevel']==0;assert win.curves[1].opts['fillLevel']==0;assert all(len(c.xData)>0 for c in win.parallel_curves);win.tabs.setCurrentIndex(2);win.refresh()\n  assert all(len(c.xData)>0 for c in win.curves)\n  assert all(abs(c.yData.max()-1)<1e-6 for c in win.curves)\n  np.testing.assert_array_equal(win.parallel_curves[1].yData,b.displayed)\n  win.scale.setCurrentIndex(1);win.refresh()\n  np.testing.assert_array_equal(win.curves[1].yData,b.displayed)\n  win.scale.setCurrentIndex(0);assert not win.plot.getAxis('right').isVisible();assert len(win.legend.items)==2;win.visible[1].setChecked(False);assert not win.curves[1].isVisible();win.visible[1].setChecked(True)\n  import tempfile\n  from pathlib import Path\n  snapshots=win.save_snapshots();assert len(snapshots)==2\n  with tempfile.TemporaryDirectory() as directory:\n   paths=win.write_snapshots(Path(directory)/'lamp.npz',snapshots)\n   assert [p.name for p in paths]==['lamp-fla5000.npz','lamp-camera.npz']\n   for path,snapshot in zip(paths,snapshots):\n    with np.load(path) as saved:np.testing.assert_array_equal(saved['corrected_counts'],snapshot[2])\n  top,bottom=[p.getViewBox() for p in win.parallel_plots]\n  top.manual_x=(450.,600.);top.setXRange(450,600,padding=0);np.testing.assert_allclose(bottom.viewRange()[0],[450,600])\n  bottom.manual_x=(460.,620.);bottom.setXRange(460,620,padding=0);win.refresh();np.testing.assert_allclose(top.viewRange()[0],[460,620]);np.testing.assert_allclose(bottom.viewRange()[0],[460,620])\n  original=b.frame_data['wave'].copy();win.set_peak_offset(2.5)\n  np.testing.assert_array_equal(win.curves[1].xData,original+2.5);np.testing.assert_array_equal(win.parallel_curves[1].xData,original+2.5);np.testing.assert_array_equal(b.frame_data['wave'],original)\n  win.set_peak_offset(0)\n  original_display=[session.displayed.copy() for session in win.sessions]\n  win.align_bottom.setChecked(True);win.scale.setCurrentIndex(1);win.refresh()\n  for curve,session in zip(win.curves,win.sessions):\n   assert abs(float(np.min(curve.yData)))<1e-8\n  for before,session in zip(original_display,win.sessions):np.testing.assert_array_equal(before,session.displayed)\n  lo,hi=win.plot.getViewBox().viewRange()[1];rlo,rhi=win.right.viewRange()[1];assert abs(-lo/(hi-lo)+rlo/(rhi-rlo))<1e-8\n  np.testing.assert_array_equal(win.parallel_curves[1].yData,b.displayed)\n  win.align_bottom.setChecked(False);win.scale.setCurrentIndex(0)\n  a.disconnect_request.emit();win.last_b=b.frame_data['index']\n except BaseException as e:errors.append(e);finish()\ndef finish():\n try:\n  if hasattr(win,'last_b'):\n   assert not win.sessions[0].ready\n   win.refresh();assert not win.device_panels[0].property('acquiring');assert win.device_panels[1].property('acquiring')\n   assert win.sessions[1].frame_data['index']>win.last_b\n  pass\n finally:win.close();app.quit()\nQtCore.QTimer.singleShot(500,begin);QtCore.QTimer.singleShot(1300,check);QtCore.QTimer.singleShot(2000,finish);app.exec()\nassert not any(s.thread.isRunning() for s in win.sessions)\nif errors:raise errors[0]\nprint('Dual acquisition, separate averages, normalized/raw overlay, hide/show, independent disconnect, thread cleanup: PASS')\n"
    result=subprocess.run([sys.executable,"-c",code],env=dict(os.environ,QT_QPA_PLATFORM="offscreen",XDG_CONFIG_HOME=str(tmp_path)),capture_output=True,text=True,timeout=30)
    assert result.returncode==0,result.stdout+result.stderr
